/*	etcReport.selectEtcCount */
SELECT
	COUNT(ETC_IDX) as cnt
FROM 	
	lab_etc
WHERE 1 = 1


		AND DOC_OWNER = #{userId} 


	    AND DOC_OWNER IN (
	    	SELECT USER_ID from lab_team_manager_view ltmv
			WHERE ltmv.TEAM_MANAGER_ID = #{userId}
	    ) 





		 AND DOC_OWNER = #{userId} 

	AND IS_DELETE = 'N'

/* etcReport.selectEtcList */ SELECT ETC_IDX , TITLE , CONTENTS , IS_DELETE , STATUS , REG_USER , DOC_OWNER , DOC_NO , FN_GET_USER_NAME(le.DOC_OWNER) as DOC_OWNER_NAME , FN_GET_CODE_NAME('DOC_STATUS', le.STATUS) AS STATUS_TXT FROM lab_etc le WHERE 1 = 1 AND DOC_NO in ( SELECT tmp.DOC_NO FROM ( SELECT row_number() over (order by ETC_IDX DESC) as rnum , DOC_NO FROM lab_etc WHERE 1 = 1
AND DOC_OWNER = #{userId}
AND DOC_OWNER IN ( SELECT USER_ID from lab_team_manager_view ltmv WHERE ltmv.TEAM_MANAGER_ID = #{userId} )
AND DOC_OWNER = #{userId}
AND IS_DELETE = 'N'
) tmp WHERE rnum between #{startRow} and #{endRow} ) ORDER BY DOC_NO DESC, ETC_IDX DESC

