/*	etcReport.insertEtc */
INSERT INTO lab_etc(
	ETC_IDX
	, TITLE
	, CONTENTS
	, IS_DELETE
	, STATUS
	, REG_USER
	, DOC_OWNER		
	, DOC_NO		
)VALUES(
	#{idx}
	, #{title}
	, #{contents}
	, 'N'
	, #{status}
	, #{userId}
	, #{userId}
	, (SELECT ifnull(MAX(ld.DOC_NO),0)+1 FROM lab_etc ld WHERE 1 = 1)	
)

